// Generated by `nuxi prepare` for a plugin that returns `provide: { shout }`.
// Nuxt writes the `$`-prefixed instance property into the same
// `ComponentCustomProperties` interface Vue tooling reads, and the signature is
// strict so a wrong-typed template call is a real TS2345.
//
// The `vue` entry in `.nuxt/tsconfig.json` `paths` is what makes this
// augmentation land on the same `vue` module the checked program uses. Without
// it a project-local `declare module "vue"` can bind to a different resolution
// of the package than the generated virtual code does, and the property goes
// back to a widened stand-in.
declare module "vue" {
  interface ComponentCustomProperties {
    $shout: (label: string) => string;
  }
}

export {};
